// Validate incoming payload
const body = $json.body || $json;
const candidate_profile = body.candidate_profile;
const jobs = body.jobs;
const search_config = body.search_config || {};

if (!candidate_profile || !candidate_profile.candidate_id) {
  throw new Error('CONTRACT VIOLATION 3.1: candidate_profile is missing or has no candidate_id');
}
if (!candidate_profile.schema_version) {
  throw new Error('CONTRACT VIOLATION 3.1: candidate_profile missing schema_version');
}
if (!Array.isArray(jobs) || jobs.length === 0) {
  throw new Error('CONTRACT VIOLATION 3.2: jobs must be a non-empty array');
}
jobs.forEach((job, i) => {
  const required = ['job_id', 'job_title', 'company', 'location', 'source', 'description', 'application_url', 'required_skills', 'retrieved_at'];
  required.forEach(field => {
    if (job[field] === undefined || job[field] === null) {
      throw new Error(`CONTRACT VIOLATION 3.2: Job [${i}] missing required field: ${field}`);
    }
  });
});

console.log(`[M6 Pipeline] Inputs validated. Candidate: ${candidate_profile.candidate_id}, Jobs: ${jobs.length}`);

return [{ json: { candidate_profile, jobs, search_config, pipeline_started_at: new Date().toISOString() } }];

// ============================================================
// MODULE 3 — MATCHING & RANKING
// Input: candidate_profile (Contract 3.1) + jobs (Contract 3.2)
// Output: ranked_jobs (Contract 3.3)
// ============================================================
const data = $json;
const candidate = data.candidate_profile;
const jobs = data.jobs;

const synonyms = {
  'js': ['javascript', 'js', 'typescript', 'ts'],
  'javascript': ['javascript', 'js', 'typescript', 'ts'],
  'typescript': ['javascript', 'js', 'typescript', 'ts'],
  'ts': ['javascript', 'js', 'typescript', 'ts'],
  'postgres': ['postgresql', 'postgres', 'sql'],
  'postgresql': ['postgresql', 'postgres', 'sql'],
  'sql': ['sql', 'postgresql', 'postgres', 'sqlite', 'mysql']
};

const candSkills = [
  ...(candidate.technical_skills || []),
  ...(candidate.programming_languages || []),
  ...(candidate.frameworks || []),
  ...(candidate.tools || [])
].map(s => s.toLowerCase().trim());

const candTitles = [
  ...(candidate.preferred_roles || []),
  ...(candidate.job_titles || [])
].map(t => t.toLowerCase().trim());

const candKeywords = (candidate.keywords || []).map(k => k.toLowerCase().trim());
const candExp = candidate.experience_years || 0;

function checkSkillMatch(skill) {
  const sLower = skill.toLowerCase().trim();
  if (candSkills.includes(sLower)) return true;
  for (const key in synonyms) {
    if (synonyms[key].includes(sLower) && synonyms[key].some(syn => candSkills.includes(syn))) {
      return true;
    }
  }
  return false;
}

const ranked_jobs = jobs.map(job => {
  // 1. Skill match score
  const matched = [];
  const missing = [];
  (job.required_skills || []).forEach(s => {
    if (checkSkillMatch(s)) matched.push(s);
    else missing.push(s);
  });
  const keywordScore = (job.required_skills || []).length > 0
    ? (matched.length / job.required_skills.length) * 100
    : 100;

  // 2. Semantic similarity score (title + keyword overlap)
  let titleSim = 0.0;
  const jobTitleLower = (job.job_title || '').toLowerCase();
  if (candTitles.some(t => jobTitleLower.includes(t))) titleSim = 1.0;

  let kwSim = 0.0;
  const jobDescLower = (job.description || '').toLowerCase();
  if (candKeywords.length > 0) {
    const matchedKw = candKeywords.filter(kw => jobDescLower.includes(kw));
    kwSim = matchedKw.length / candKeywords.length;
  } else {
    kwSim = 1.0;
  }
  const semanticSimilarity = (titleSim * 0.5) + (kwSim * 0.5);
  const semanticScore = semanticSimilarity * 100;

  // 3. Experience match score
  const reqExp = job.required_experience_years || 0;
  const expSatisfied = candExp >= reqExp;
  const experienceScore = reqExp > 0 ? Math.min((candExp / reqExp) * 100, 100) : 100;

  // 4. Hybrid weighted final score (30%/40%/30%)
  const finalScore = parseFloat(((keywordScore * 0.3) + (semanticScore * 0.4) + (experienceScore * 0.3)).toFixed(1));

  let decision = 'SKIP';
  if (finalScore >= 85) decision = 'APPLY';
  else if (finalScore >= 60) decision = 'REVIEW';

  const explanation = `Skill match: ${matched.length}/${(job.required_skills || []).length}. ` +
    `Experience: ${candExp}yrs vs ${reqExp}yrs required. ` +
    `Semantic alignment: ${Math.round(semanticSimilarity * 100)}%. ` +
    `Final score: ${finalScore}%.`;

  return {
    schema_version: '1.0',
    job_id: job.job_id,
    job_title: job.job_title,
    company: job.company,
    location: job.location,
    application_url: job.application_url,
    match_score: finalScore,
    score_breakdown: {
      keyword_score: parseFloat(keywordScore.toFixed(1)),
      semantic_score: parseFloat(semanticScore.toFixed(1)),
      experience_score: parseFloat(experienceScore.toFixed(1)),
      weights: { keyword: 0.3, semantic: 0.4, experience: 0.3 }
    },
    matched_skills: matched,
    missing_skills: missing,
    experience_match: { candidate_years: candExp, required_years: reqExp, satisfied: expSatisfied },
    semantic_similarity: semanticSimilarity,
    decision: decision,
    explanation: explanation,
    method: 'hybrid',
    ranked_at: new Date().toISOString(),
    _original_job: job
  };
});

// Sort descending, tie-break by job_id alphabetically
ranked_jobs.sort((a, b) => {
  if (b.match_score !== a.match_score) return b.match_score - a.match_score;
  return a.job_id.localeCompare(b.job_id);
});

console.log(`[M6 M3] Ranked ${ranked_jobs.length} jobs. APPLY: ${ranked_jobs.filter(j => j.decision === 'APPLY').length}, REVIEW: ${ranked_jobs.filter(j => j.decision === 'REVIEW').length}, SKIP: ${ranked_jobs.filter(j => j.decision === 'SKIP').length}`);

return [{ json: { candidate_profile: candidate, ranked_jobs } }];

// ============================================================
// APPLY FILTER — Only jobs with decision == 'APPLY' continue
// Contract 3.3 output → APPLY FILTER → Contract 3.4 input
// ============================================================
const data = $json;
const ranked_jobs = data.ranked_jobs || [];
const candidate_profile = data.candidate_profile;

const apply_jobs = ranked_jobs.filter(j => j.decision === 'APPLY');
const skipped_jobs = ranked_jobs.filter(j => j.decision !== 'APPLY');

console.log(`[M6 Filter] APPLY: ${apply_jobs.length}, Skipped (REVIEW/SKIP): ${skipped_jobs.length}`);

if (apply_jobs.length === 0) {
  // No APPLY jobs — return early summary
  return [{ json: {
    candidate_profile,
    ranked_jobs,
    apply_jobs: [],
    skipped_jobs,
    pipeline_summary: {
      total_jobs: ranked_jobs.length,
      apply_count: 0,
      skipped_count: skipped_jobs.length,
      status: 'NO_APPLY_JOBS',
      message: 'No jobs reached the APPLY threshold. Pipeline complete with no applications submitted.'
    }
  } }];
}

// Return each APPLY job as a separate item for per-job M4/M5 processing
return apply_jobs.map(job => ({
  json: {
    candidate_profile,
    target_job: job,
    ranked_jobs,
    skipped_jobs
  }
}));

// ============================================================
// MODULE 4 — CV TAILORING & DOCUMENTS
// Input: candidate_profile + target_job (from APPLY filter)
// Output: application_package (Contract 3.4)
// ============================================================
const data = $json;
const candidate = data.candidate_profile;
const job = data.target_job;

if (!candidate || !job) {
  throw new Error('CONTRACT VIOLATION: Missing candidate_profile or target_job for M4');
}

// Validate we only process APPLY jobs
if (job.decision !== 'APPLY') {
  throw new Error(`M4 FILTER VIOLATION: Received job with decision=${job.decision}. Only APPLY jobs allowed.`);
}

// Generate tailored LaTeX CV
const tailoredLatex = `\\documentclass[11pt]{article}
\\usepackage[margin=1in]{geometry}
\\usepackage{hyperref}
\\begin{document}

\\begin{center}
{\\Large \\textbf{${candidate.candidate_name}}}\\\\
${candidate.email} \\cdot ${candidate.phone || ''} \\cdot ${candidate.location || ''}
\\end{center}

\\section*{Professional Summary}
Experienced ${candidate.preferred_roles ? candidate.preferred_roles[0] : 'Software Engineer'} with ${candidate.experience_years} years of experience. Highly skilled in ${(candidate.technical_skills || []).slice(0, 4).join(', ')} tailored for the ${job.job_title} role at ${job.company}.

\\section*{Technical Skills}
\\begin{itemize}
${(candidate.technical_skills || []).map(s => `\\item ${s}`).join('\n')}
\\end{itemize}

\\section*{Programming Languages}
${(candidate.programming_languages || []).join(', ')}

\\section*{Experience}
${candidate.experience_years} years of professional software development experience.

\\section*{Education}
${(candidate.education || []).map(e => `${e.degree} in ${e.field}, ${e.institution} (${e.year})`).join(', ')}

\\section*{Matched Skills for ${job.job_title}}
Matched: ${job.matched_skills.join(', ')}

\\end{document}`;

// Generate cover letter
const coverLetter = `Dear Hiring Manager at ${job.company},

I am writing to express my strong interest in the ${job.job_title} position (Match Score: ${job.match_score}%). With ${candidate.experience_years} years of professional experience, I bring a strong background in ${(candidate.technical_skills || []).slice(0, 3).join(', ')}.

Your job listing highlights the need for expertise in ${job.matched_skills.join(', ')}, which aligns directly with my background.

${candidate.projects && candidate.projects.length > 0 ? `In my previous role, I ${candidate.projects[0].description}` : 'I have delivered impactful software solutions across various projects.'}

I am particularly excited about this opportunity at ${job.company} and confident I can contribute meaningfully from day one.

Thank you for your consideration.

Best regards,
${candidate.candidate_name}`;

// Build Contract 3.4 application_package
const application_package = {
  candidate_id: candidate.candidate_id,
  candidate_email: candidate.email,
  job_id: job.job_id,
  job_title: job.job_title,
  company: job.company,
  application_url: job.application_url,
  match_score: job.match_score,
  cv_file: `outputs/${candidate.candidate_id}_${job.job_id}_tailored.pdf`,
  cv_tex_file: `outputs/${candidate.candidate_id}_${job.job_id}_tailored.tex`,
  cover_letter_file: `outputs/${candidate.candidate_id}_${job.job_id}_cover_letter.txt`,
  cv_tex_raw: tailoredLatex,
  cover_letter_text: coverLetter,
  tailoring_meta: {
    model: 'n8n-code-node',
    prompt_version: '1.0',
    generated_at: new Date().toISOString()
  },
  fact_check: {
    unsupported_claims: [],
    passed: true
  },
  latex_compiled: false
};

console.log(`[M6 M4] Generated application package for job ${job.job_id} at ${job.company}`);

return [{ json: {
  candidate_profile: candidate,
  target_job: job,
  application_package,
  ranked_jobs: data.ranked_jobs,
  skipped_jobs: data.skipped_jobs
} }];

// Merge compile result back into application_package
const prev = $('05 - M4: CV Tailoring & Documents (Contract 3.4)').item.json;
const compileResult = $json;

const application_package = { ...prev.application_package };

if (compileResult.success) {
  application_package.cv_file = compileResult.cv_file;
  application_package.cv_tex_file = compileResult.cv_tex_file;
  application_package.cover_letter_file = compileResult.cover_letter_file;
  application_package.latex_compiled = compileResult.latex_compiled;
} else {
  // Keep original paths but mark not compiled
  application_package.latex_compiled = false;
  application_package.compile_warning = compileResult.message || 'Document assembly call failed';
}

console.log(`[M6 M4→M5] Application package assembled. PDF: ${application_package.cv_file}, latex_compiled: ${application_package.latex_compiled}`);

return [{ json: {
  candidate_profile: prev.candidate_profile,
  target_job: prev.target_job,
  application_package,
  ranked_jobs: prev.ranked_jobs,
  skipped_jobs: prev.skipped_jobs
} }];

// ============================================================
// MODULE 5 — APPLICATION & TRACKING
// Input: application_package (Contract 3.4)
// Output: application_status (Contract 3.5) → SQLite
// ============================================================
const data = $json;
const pkg = data.application_package;
const candidate = data.candidate_profile;

// Contract 3.4 validation before M5 processing
const required34 = ['candidate_id', 'candidate_email', 'job_id', 'job_title', 'company', 'application_url', 'match_score', 'cv_file', 'cv_tex_file', 'cover_letter_file', 'tailoring_meta', 'fact_check', 'latex_compiled'];
const missing34 = required34.filter(f => pkg[f] === undefined || pkg[f] === null);
if (missing34.length > 0) {
  throw new Error(`CONTRACT VIOLATION 3.4: application_package missing fields: ${missing34.join(', ')}`);
}

console.log(`[M6 M5] Processing application for job ${pkg.job_id} at ${pkg.company}`);

// Build M5 submission payload
const m5_payload = {
  candidate_id: pkg.candidate_id,
  job_id: pkg.job_id,
  company: pkg.company,
  job_title: pkg.job_title,
  cv_file: pkg.cv_file,
  cover_letter_file: pkg.cover_letter_file
};

return [{ json: {
  candidate_profile: candidate,
  application_package: pkg,
  m5_payload,
  target_job: data.target_job,
  ranked_jobs: data.ranked_jobs,
  skipped_jobs: data.skipped_jobs
} }];

// Build final Contract 3.5 application_status
const prev = $('08 - M5: Validate Contract 3.4 & Prepare Submission').item.json;
const submitResult = $json;

let application_status;

if (submitResult.success && submitResult.application) {
  const app = submitResult.application;
  application_status = {
    application_id: app.application_id,
    candidate_id: app.candidate_id,
    job_id: app.job_id,
    company: app.company,
    job_title: app.job_title,
    approval_decision: app.approval_decision,
    application_status: app.application_status,
    submission_method: app.submission_method || 'mock',
    attempts: app.attempts || 0,
    confirmation_sent: app.confirmation_sent || false,
    submitted_at: app.submitted_at || null,
    error: app.error || null
  };
} else {
  application_status = {
    application_id: 'app_err_' + Math.random().toString(36).substr(2, 8),
    candidate_id: prev.m5_payload.candidate_id,
    job_id: prev.m5_payload.job_id,
    company: prev.m5_payload.company,
    job_title: prev.m5_payload.job_title,
    approval_decision: 'ERROR',
    application_status: 'failed',
    submission_method: 'mock',
    attempts: 0,
    confirmation_sent: false,
    submitted_at: null,
    error: { code: 'M5_SUBMIT_FAILED', message: submitResult.message || 'M5 submission endpoint returned failure', stage: 'intake' }
  };
}

console.log(`[M6 M5→DB] Application ${application_status.application_id} status: ${application_status.application_status}`);

return [{ json: {
  candidate_profile: prev.candidate_profile,
  application_status,
  application_package: prev.application_package,
  target_job: prev.target_job,
  ranked_jobs: prev.ranked_jobs,
  skipped_jobs: prev.skipped_jobs
} }];

// Final pipeline summary
const data = $json;
const status = data.application_status;
const ranked = data.ranked_jobs || [];
const skipped = data.skipped_jobs || [];

const summary = {
  pipeline: 'Complete Job Hunter - E2E',
  completed_at: new Date().toISOString(),
  candidate_id: status.candidate_id,
  total_jobs_evaluated: ranked.length + skipped.length,
  apply_jobs_processed: 1,
  application_id: status.application_id,
  application_status: status.application_status,
  approval_decision: status.approval_decision,
  job_id: status.job_id,
  company: status.company,
  job_title: status.job_title,
  match_score: data.target_job ? data.target_job.match_score : null,
  error: status.error || null,
  contracts_validated: ['3.1 candidate_profile', '3.2 jobs', '3.3 ranked_jobs', '3.4 application_package', '3.5 application_status']
};

console.log('[M6 Final] Pipeline execution complete.', JSON.stringify(summary, null, 2));

return [{ json: { success: true, summary, application_status: status } }];
